'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const model=require('./nano-stock-forecast-198.js');
const calc=model.recommend;
// Read-only deterministic coverage formula; no inventory mutation.
const source={stock:8,minimum:4,avgDaily:2,baselineOrder:2};
const original=JSON.stringify(source);
const a=calc(source);
assert.equal(a.ok,true);assert.equal(a.avgDaily,2);
assert.equal(a.coverDays,4);
assert.equal(a.order,30); // 2 units/day * (14+3 days) + 4 buffer - 8 stock
assert.equal(JSON.stringify(source),original,'calculator must never mutate inputs');
assert.equal(calc({stock:8,minimum:4,avgDaily:0,baselineOrder:3}).order,3);
assert.equal(calc({stock:8,minimum:4,avgDaily:0,baselineOrder:3}).coverDays,null);
assert.equal(calc({stock:8,minimum:4,avgDaily:null,baselineOrder:3}).ok,false);
assert.equal(calc({stock:-1,minimum:4,avgDaily:2}).ok,false);
assert.equal(calc({stock:8,minimum:4,avgDaily:-2}).ok,false);
assert.equal(calc({stock:8,minimum:4,avgDaily:2,horizonDays:100}).ok,false);
assert.equal(calc({stock:500,minimum:50,avgDaily:0.2,baselineOrder:0}).order,0);
assert.equal(calc({stock:1.5,minimum:0,avgDaily:0.1,baselineOrder:0}).order,0.2);
assert.equal(calc({stock:0,minimum:0,avgDaily:0,baselineOrder:1}).order,1);
const ui=fs.readFileSync('nano-inventory-shortages.js','utf8');
const index=fs.readFileSync('index.html','utf8');
const pkg=JSON.parse(fs.readFileSync('package.json','utf8'));
assert.equal(pkg.version,'1.0.98');
assert.ok(ui.includes("getProductAnalytics(row.id)"),'use existing read-only analytics service');
assert.ok(ui.includes('async function estimateDemand()'));
assert.ok(ui.includes('Math.min(3,candidates.length)'),'bounded analytics concurrency');
assert.ok(ui.includes('snapshot.slice(0,60)'),'bounded scope');
assert.ok(ui.includes('nanoShortageForecast198'),'button must be reachable from existing shortages modal');
assert.ok(ui.includes('root.api.getProducts({page,perPage:200})'),'preserve existing paged inventory reader');
assert.ok(ui.includes('function downloadCSV()'),'existing CSV flow remains');
assert.ok(ui.includes('function printList()'),'existing print flow remains');
assert.ok(ui.includes("root.NANO_STOCK_FORECAST_198.recommend("));
assert.doesNotMatch(ui,/root\.api\.(?:save|delete|create|update|process|purchase|add)/i,'forecast must never write business data');
const first=index.indexOf('src="nano-stock-forecast-198.js"');
const second=index.indexOf('src="nano-inventory-shortages.js"');
assert.ok(first>0 && first<second,'forecast helper loads before existing inventory UI');
assert.equal((index.match(/src="nano-stock-forecast-198\.js"/g)||[]).length,1);
assert.ok(index.includes('src="nano-sales-safe-195.js"'),'sale safety module preserved');
assert.ok(index.includes('src="nano-v146-section-search.js"'),'search fix preserved');
console.log('PASS: coverage/reorder math, no mutations, bounded analytics, export, rendering hook, retained modules.');
